import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Read number of test cases, assuming 1 as in original code
        int t = 1;
        // Generate permutations of [1, 2, 3, 4, 5, 6]
        List<int[]> perms = new ArrayList<>();
        permute(new int[]{1, 2, 3, 4, 5, 6}, 0, perms);

        int n = Integer.parseInt(br.readLine().trim());
        int[] a = parseLineToIntArray(br.readLine());
        int[] b = parseLineToIntArray(br.readLine());

        int max_possible = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int max_score = 0;

        for (int[] perm : perms) {
            int[] a_copy = a.clone();
            int[] b_copy = b.clone();
            int score = 0;
            for (int el : perm) {
                int t = 0;
                switch (el) {
                    case 1:
                        t = Math.min(a_copy[0], b_copy[0]);
                        a_copy[0] -= t;
                        b_copy[0] -= t;
                        break;
                    case 2:
                        t = Math.min(a_copy[0], b_copy[2]);
                        a_copy[0] -= t;
                        b_copy[2] -= t;
                        break;
                    case 3:
                        t = Math.min(a_copy[1], b_copy[1]);
                        a_copy[1] -= t;
                        b_copy[1] -= t;
                        break;
                    case 4:
                        t = Math.min(a_copy[1], b_copy[0]);
                        a_copy[1] -= t;
                        b_copy[0] -= t;
                        break;
                    case 5:
                        t = Math.min(a_copy[2], b_copy[2]);
                        a_copy[2] -= t;
                        b_copy[2] -= t;
                        break;
                    case 6:
                        t = Math.min(a_copy[2], b_copy[1]);
                        a_copy[2] -= t;
                        b_copy[1] -= t;
                        break;
                }
                score += t;
            }
            max_score = Math.max(max_score, score);
        }
        System.out.print((n - max_score) + " " + max_possible);
    }

    static void permute(int[] arr, int l, List<int[]> perms) {
        if (l == arr.length - 1) {
            perms.add(arr.clone());
        } else {
            for (int i = l; i < arr.length; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, perms);
                swap(arr, l, i);
            }
        }
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    static int[] parseLineToIntArray(String line) {
        String[] parts = line.trim().split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }
}
